<template>
  <section class="route-judgment" aria-label="对华天然铀供应链事前研判五方法">
    <div class="heading"><div><span class="eyebrow">SUPPLY CHAIN VULNERABILITY · {{ library.as_of }}</span><h3>{{ library.title }}</h3><p>识别失效位置 → 检查整链传播 → 找到关键节点与处置时限</p></div><span class="status">五方法已计算 · 概率尚未识别</span></div>
    <div class="case-question"><b>本轮研判问题</b><p>{{ library.case_question }}</p><p class="muted">{{ library.case_boundary }}</p></div>
    <p class="position">{{ library.method_position }}</p>

    <div class="model-picker" role="group" aria-label="专业研判方法选择">
      <article v-for="(m,i) in library.models" :key="m.id">
        <button class="model-choice" :class="{active:m.id===model.id}" :aria-pressed="m.id===model.id" @click="modelId=m.id"><small>METHOD 0{{ i+1 }}</small><strong>{{ m.short }}</strong><span>{{ m.question }}</span><em>{{ m.category }}</em></button>
        <details class="method-source" :data-model-source="m.id"><summary>{{ m.short }} · 方法来源</summary><div class="source-body"><p v-for="r in m.references" :key="r.url"><a :href="r.url" target="_blank" rel="noopener noreferrer">{{ r.title }} ↗</a><br>{{ r.authors }} · {{ r.year }}<br>{{ r.publisher }}</p><p><b>本案实现：</b>{{ m.implementation }}</p><p><b>边界：</b>{{ m.boundary }}</p></div></details>
      </article>
    </div>

    <div class="controls"><label>供应链结构 <select v-model="profileId" aria-label="研判供应链结构"><option v-for="p in library.profiles" :key="p.id" :value="p.id">{{ p.label }}</option></select></label><span>{{ profile.assumption }}</span></div>
    <div class="chain" aria-label="可点击的供应链功能依赖">
      <div class="chain-stage"><small>01 供料分支</small><button @click="nodeId='acid'">硫酸 → 新生产</button><div class="branch"><button @click="nodeId='inkai'">Inkai</button><span>或</span><button @click="nodeId='other_mines'">其他合格矿源</button></div><button @click="nodeId='product'">精矿制备 / 质量放行</button><button v-if="profile.stock" class="conditional" @click="nodeId='stock'">或：已承诺成品库存</button></div>
      <span class="arrow">→</span><div class="chain-stage"><small>02 共同履约条件</small><button @click="nodeId='allocation'">订单分配与放货</button><button @click="nodeId='export'">出口 / 承运文件</button><button @click="nodeId='kz_rail'">境内铁路服务</button></div>
      <span class="arrow">→</span><div class="chain-stage"><small>03 跨境接口</small><button @click="nodeId='dostyk'">多斯特克</button><button @click="nodeId='alashankou'">阿拉山口</button><button v-if="profile.alternate" class="conditional" @click="nodeId='khorgos'">或：阿尔滕科尔 → 霍尔果斯</button><span class="micro">备用口岸仅在全部资格落实的条件中启用</span></div>
      <span class="arrow">→</span><div class="chain-stage"><small>04 企业可用</small><button @click="nodeId='import'">进口 / 交接手续</button><button @click="nodeId='acceptance'">企业到库验收</button><span class="micro">过境 ≠ 到库可用</span></div>
    </div>
    <div class="node-inspector"><div><span class="eyebrow">{{ node.stage }} · {{ node.evidence_status }}</span><h4>{{ node.label }}</h4><p><b>可能失效：</b>{{ node.failure_mode }}</p><p>{{ node.evidence_note }}</p><p><b>需核实：</b>{{ node.action }}</p></div><div><b>{{ nodeEffect.effect }}</b><p>结构关键性由完整链计算；本单当前运行状态与未来失效概率仍待核实。</p><details class="method-source"><summary>节点证据来源（{{ nodeSources.length }}）</summary><div class="source-body"><p v-if="!nodeSources.length">沿用原案例的企业需求、库存及订单设定；不是公开企业经营记录。</p><div v-for="e in nodeSources" :key="e.id"><a v-for="url in e.urls" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{ e.title || e.id }} ↗</a><p>统计期：{{ e.date }}；披露：{{ e.published_at }}</p><p>{{ e.summary }}</p><p class="muted">{{ e.limitations }}</p></div></div></details></div></div>

    <div class="formal-heading"><h4>{{ model.label }}</h4><span>{{ model.category }}</span></div>
    <div class="formal-grid"><section><small>01 · INPUT</small><h4>输入</h4><ul><li v-for="v in model.inputs" :key="v">{{ v }}</li></ul></section><section><small>02 · FORMULATION</small><h4>公式与变量</h4><code v-for="v in model.formulas" :key="v">{{ v }}</code><p v-for="v in model.variables" :key="v">{{ v }}</p></section><section><small>03 · SOLVER / OUTPUT</small><h4>求解与输出</h4><p>{{ model.solver }}</p><ul><li v-for="v in model.outputs" :key="v">{{ v }}</li></ul><p class="muted">{{ model.implementation }}</p></section></div>

    <div v-if="model.id==='fmea'" class="output-panel">
      <h4>失效工作表 · 从风险证据到整链影响</h4><p class="muted">RPN需要严重度、发生度、难检测度的有据量表，本案均未赋分。下表按功能失效后果识别优先核实对象。</p>
      <div class="table-wrap"><table><thead><tr><th>风险位置</th><th>可能失效 / 证据</th><th>完整链影响</th><th>监测与核实动作</th></tr></thead><tbody><tr v-for="r in profile.fmea.filter(r=>r.active)" :key="r.id" :class="{focused:r.id===nodeId}"><th><button class="link-button" @click="nodeId=r.id">{{ r.label }}</button></th><td>{{ r.failure_mode }}<small>{{ r.evidence_status }}</small></td><td>{{ r.effect }}<small>失去{{ r.lost_path_combinations }}个逻辑组合；剩余{{ r.remaining_paths }}个</small></td><td>{{ r.action }}</td></tr></tbody></table></div>
    </div>
    <div v-else-if="model.id==='fta'" class="output-panel">
      <h4>顶事件：没有任何完整交付通路</h4><p class="muted">共{{ profile.cuts.length }}组最小割集。组内同时失效（AND），任一组出现即可阻断（OR）。不是故障发生概率。</p>
      <div class="cut-grid"><article v-for="cut in profile.cuts" :key="cut.join()"><small>{{ cut.length===1?'单个功能完全失效':'AND · 联合失效' }}</small><strong>{{ cut.map(label).join(' ＋ ') }}</strong><span>已验证：删除组内任一失效条件后，完整通路恢复存在</span></article></div>
    </div>
    <div v-else-if="model.id==='interdiction'" class="output-panel">
      <div class="metrics"><article><span>N−1 检验</span><strong>{{ profile.network.n1_count }}<small>个功能节点</small></strong></article><article><span>N−2 检验</span><strong>{{ profile.network.n2_count }}<small>组</small></strong></article><article><span>单点阻断功能</span><strong>{{ profile.network.single_points.length }}<small>个</small></strong></article><article><span>口岸分支</span><strong>{{ profile.border_corridor_count }}<small>条 / 当前结构</small></strong></article></div>
      <p>需要优先确认的共同依赖：<b>{{ profile.network.single_points.map(label).join('、') }}</b>。</p><p class="muted">上述数量以抽象功能为单位。“其他矿源”或“境内铁路”移除表示整个功能不可用，不等于一座设施故障。备用口岸增加后，共同履约条件仍然可能单点阻断。</p>
      <div class="table-wrap"><table><thead><tr><th>两项单独失效均可绕开，但合并会阻断的组合</th><th>剩余完整通路</th></tr></thead><tbody><tr v-for="r in profile.network.minimal_pair_failures" :key="r.nodes.join()"><td>{{ r.labels.join(' ＋ ') }}</td><td>{{ r.remaining_paths }}</td></tr></tbody></table></div>
      <label class="test-toggle"><input v-model="showNetworkTests" type="checkbox"> 显示全部N−1/N−2求解记录</label><div v-if="showNetworkTests" class="table-wrap long-table"><table><thead><tr><th>移除功能</th><th>剩余组合</th><th>服务可达性F</th></tr></thead><tbody><tr v-for="r in profile.network.tests" :key="r.nodes.join()"><td>{{ r.labels.join(' ＋ ') }}</td><td>{{ r.remaining_paths }}</td><td>{{ r.service }} · {{ r.disconnected?'无完整通路':'仍有逻辑通路' }}</td></tr></tbody></table></div>
    </div>
    <div v-else-if="model.id==='petri'" class="output-panel">
      <div class="controls"><label>流程阻塞检验 <select v-model="petriId" aria-label="Petri网失效条件"><option v-for="r in profile.petri.runs" :key="r.id" :value="r.id">{{ r.label }}</option></select></label></div>
      <div class="petri-result" :class="{blocked:!petri.reachable}"><b>{{ petri.reachable?'存在可达交付路径':'交付不可达' }}</b><span>遍历{{ petri.reachable_places.length }}个订单状态；每次转移前后总托肯数=1。</span></div>
      <p v-if="petri.witness" class="trace">{{ petri.witness.map(transitionLabel).join(' → ') }}</p>
      <div class="table-wrap"><table><thead><tr><th>遇到的阻塞变迁</th><th>缺失的就绪条件</th><th>到达该处前的流转</th></tr></thead><tbody><tr v-for="b in petri.blocked_transitions" :key="b.transition"><td>{{ transitionLabel(b.transition) }}</td><td>{{ b.failed_guards.map(label).join('、') }}</td><td>{{ b.trace.length?b.trace.map(transitionLabel).join(' → '):'订单起点' }}</td></tr><tr v-if="!petri.blocked_transitions.length"><td colspan="3">该测试条件下没有阻塞；这是所有守卫成立时的结构基准，不是对当前订单手续的认定。</td></tr></tbody></table></div>
      <p class="muted">分支存在阻塞时仍可能通过其他分支交付。这里只验证状态可达性，不估计排队、运输时间或准点率。</p>
    </div>
    <div v-else class="output-panel">
      <p>本项沿用原四批订单，单独检验2026年11月10日起的交付停顿；上方库存/口岸资格开关不自动生成替代到货。</p>
      <div class="metrics"><article><span>所有后续收货受阻的TTS</span><strong>{{ library.tts.all_orders_exposed.tts_days }}<small>个完整日</small></strong></article><article><span>必须补入的验收可用日</span><strong class="date">{{ library.tts.all_orders_exposed.latest_acceptance_date }}</strong></article><article><span>全部未交付时的期末目标缺口</span><strong>{{ format(library.tts.all_orders_exposed.missing_tu_for_closing_target) }}<small>tU</small></strong></article></div>
      <p><b>{{ library.tts.repair_deadline }}</b></p>
      <div class="table-wrap"><table><thead><tr><th>节点</th><th>暴露映射</th><th>TTS可识别范围</th></tr></thead><tbody><tr v-for="r in library.tts.rows.filter(r=>r.mapping!=='not_in_base')" :key="r.node_id"><th>{{ r.label }}</th><td>{{ r.interpretation }}</td><td>{{ r.tts_lower_days }}天 — ≥{{ r.tts_upper_days }}天</td></tr></tbody></table></div>
      <p class="muted">下界表示全部未来收货都依赖该节点；上界表示没有订单暴露，且仅观察到12月31日。没有订单—矿源—在途位置映射时不能给每个矿山一个确定TTS。期末目标独立于阶段不断料检验。</p>
      <div class="table-wrap"><table><thead><tr><th>仅一批永久无法到货</th><th>无损供料天数（11月10日起）</th><th>首个欠料日</th><th>期末目标缺口 tU</th></tr></thead><tbody><tr v-for="r in library.tts.single_order_cases" :key="r.label"><th>{{ r.label }}</th><td>{{ r.right_censored?'≥':'' }}{{ r.tts_days }}</td><td>{{ r.first_unserved_date || '窗口内未触发' }}</td><td>{{ format(r.missing_tu_for_closing_target) }}</td></tr></tbody></table></div>
    </div>
    <p class="model-boundary">{{ model.boundary }}</p>
    <div class="conclusions"><h4>本案已经回答什么</h4><p v-for="s in library.findings" :key="s">{{ s }}</p><p><b>中断发生概率：</b>当前资料不能识别；发现结构断点不等于预测它会中断。</p><p><b>下一步应补：</b>{{ library.data_status.required_next.join('；') }}。</p></div>
    <details class="method-source evidence-ledger"><summary>数据来源与模型输入台账 · {{ library.evidence.length }}条记录</summary><p>{{ library.provenance.case_input_source }}</p><div class="table-wrap long-table"><table><thead><tr><th>来源 / 披露日期</th><th>数据及单位</th><th>支持什么 / 限制</th></tr></thead><tbody><tr v-for="e in library.evidence" :key="e.id"><td><a v-for="url in e.urls" :key="url" :href="url" target="_blank" rel="noopener noreferrer">{{ e.title || e.id }} ↗</a><small>{{ e.published_at }}</small></td><td><code>{{ typeof e.value==='object'?JSON.stringify(e.value):e.value }}</code>{{ e.unit }}</td><td>{{ e.summary }}<small>{{ e.limitations }}</small><small v-if="e.cutoff_note">{{ e.cutoff_note }}</small></td></tr></tbody></table></div></details>
  </section>
</template>

<script setup>
import {ref,computed} from 'vue'
const props=defineProps({library:{type:Object,required:true}})
const modelId=ref('fmea'), profileId=ref('fresh_single'), nodeId=ref('alashankou'), petriId=ref('border'), showNetworkTests=ref(false)
const model=computed(()=>props.library.models.find(m=>m.id===modelId.value)||props.library.models[0])
const profile=computed(()=>props.library.profiles.find(p=>p.id===profileId.value)||props.library.profiles[0])
const node=computed(()=>props.library.nodes.find(n=>n.id===nodeId.value)||props.library.nodes[0])
const nodeEffect=computed(()=>profile.value.fmea.find(n=>n.id===node.value.id))
const nodeSources=computed(()=>props.library.evidence.filter(e=>node.value.evidence_ids.includes(e.id)))
const petri=computed(()=>profile.value.petri.runs.find(r=>r.id===petriId.value)||profile.value.petri.runs[0])
const label=id=>props.library.nodes.find(n=>n.id===id)?.label||id
const format=v=>Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2})
const transitionLabel=id=>({mine_inkai:'Inkai供料',mine_other:'其他矿源供料',release_inkai:'Inkai精矿放行',release_other:'其他矿源精矿放行',stock_release:'已承诺库存释放',allocate:'订单分配',dispatch:'出口/承运准备',rail:'境内铁路',cross_dostyk:'多斯特克移交',handover_ala:'阿拉山口接收',cross_alt:'阿尔滕科尔移交',handover_khorgos:'霍尔果斯接收',import:'进口交接',accept:'企业验收'}[id]||id)
</script>

